abstract class Pembayaran {
  constructor(public jumlah: number) {}
  abstract biaya(): number;
  abstract nama(): string;
  ringkasan(): string {
    return `${this.nama()}: ${this.jumlah + this.biaya()}`;
  }
}
class Transfer extends Pembayaran {
  biaya(): number {
    return 2500;
  }
  nama(): string {
    return "Transfer";
  }
}
class QRIS extends Pembayaran {
  biaya(): number {
    return Math.round(this.jumlah * 0.007);
  }
  nama(): string {
    return "QRIS";
  }
}
const semua: Pembayaran[] = [new Transfer(50000), new QRIS(50000)];
semua.forEach((p) => console.log(p.ringkasan()));

