abstract class ProdukBank {
  constructor(public pemilik: string, protected saldo: number) {}
  abstract persenBunga(): number;
  saldoAkhirTahun(): number {
    return Math.round(this.saldo * (1 + this.persenBunga() / 100));
  }
}
class Tabungan extends ProdukBank {
  persenBunga(): number {
    return 2;
  }
}
console.log(new Tabungan("Rina", 1000000).saldoAkhirTahun());

