cards.solution:
abstract class Laporan {
  abstract judul(): string;
  abstract baris(): string[];
  cetak(): void {
    console.log(this.judul());
    for (const b of this.baris()) console.log("- " + b);
  }
}
class LaporanStok extends Laporan {
  judul(): string {
    return "Stok";
  }
  baris(): string[] {
    return ["Gula 5", "Beras 12"];
  }
}
new LaporanStok().cetak();
